function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

const input = items[0]?.json || {};
const check = input.technical_check || {};

return [
 {
   json: {
     ...input,
     technical_check_execution: {
       technical_check_id: makeId('techcheck'),
       check_id: check.check_id,
       check_name: check.check_name,
       component: check.component,
       check_type: check.check_type,
       critical: Boolean(check.critical),
       started_at: new Date().toISOString()
     }
   }
 }
];

const context = $('Prepare Technical Check').first().json || {};
const rows = items.map(item => item.json || {});

const hasError = rows.some(row =>
 row.error ||
 row.errorMessage ||
 row.errorDescription
);

const errors = [];
const warnings = [];

if (hasError) {
 errors.push({
   code: 'supabase_query_failed',
   detail: rows
 });
}

const status = errors.length > 0 ? 'failed' : 'passed';

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status,
       actual_result: {
         connection_ok: !hasError,
         rows_returned: rows.length
       },
       evidence: {
         sample_rows_available: rows.length > 0,
         raw_sample: rows.slice(0, 1)
       },
       errors,
       warnings
     }
   }
 }
];

function makeId(prefix) {
 return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

const input = items[0]?.json || {};
const config = input.technical_config || {};
const ctx = config.test_context || {};

const eventId = makeId('evt_m8_health');

const event = {
 schema_version: 'dalia.m8.event_request.v1',
 event: {
   event_id: eventId,
   event_name: 'technical_health_check',
   event_type: 'system',
   module: 'M11',
   status: 'success',
   level: 'INFO',
   timestamp: new Date().toISOString(),

   trace: {
     conversation_id: `conv_${ctx.channel}_${ctx.user_id}`,
     session_id: `session_${ctx.channel}_${ctx.user_id}`
   },

   context: {
     business_id: ctx.business_id || 'business_demo',
     environment: config.environment || 'demo',
     channel: ctx.channel || 'whatsapp',
     user_id: ctx.user_id || '',
     display_name: ctx.display_name || 'Tester Técnico'
   },

   correlation: {
     correlation_id: eventId,
     trace_id: eventId
   },

   payload: {
     check_type: 'm8_logging_readiness',
     source: 'M11 technical rehearsal'
   }
 }
};

return [
 {
   json: {
     ...input,
     m8_health_event_id: eventId,
     m8_event_request: event
   }
 }
];

const context = $('Build M8 Health Event').first().json || {};
const m8Result = items[0]?.json || {};

const success = Boolean(m8Result.success);

const errors = [];
const warnings = [];

if (!success) {
 errors.push({
   code: 'm8_event_not_logged',
   detail: m8Result
 });
}

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status: success ? 'passed' : 'failed',
       actual_result: {
         event_logged: success,
         event_id: context.m8_health_event_id || ''
       },
       evidence: {
         m8_result: m8Result
       },
       errors,
       warnings
     }
   }
 }
];

const context = $('Prepare Technical Check').first().json || {};
const rows = items.map(item => item.json || {});

const errors = [];
const warnings = [];

const hasError = rows.some(row =>
 row.error ||
 row.errorMessage ||
 row.errorDescription
);

if (hasError) {
 errors.push({
   code: 'catalog_source_query_failed',
   detail: rows
 });
}

if (!hasError && rows.length === 0) {
 errors.push({
   code: 'catalog_source_empty',
   detail: 'No se encontraron filas en el catálogo.'
 });
}

const validLikeCatalog = rows.some(row =>
 row.sku ||
 row.SKU ||
 row.product_id ||
 row.titulo ||
 row.título ||
 row.display_name ||
 row.nombre ||
 row.producto
);

if (!hasError && rows.length > 0 && !validLikeCatalog) {
 warnings.push({
   code: 'catalog_rows_without_expected_fields',
   detail: 'Hay filas, pero no se detectaron campos típicos de catálogo.'
 });
}

const status =
 errors.length > 0
   ? 'failed'
   : warnings.length > 0
     ? 'warning'
     : 'passed';

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status,
       actual_result: {
         catalog_rows_found: rows.length > 0,
         rows_count: rows.length,
         valid_like_catalog: validLikeCatalog
       },
       evidence: {
         sample_rows: rows.slice(0, 3)
       },
       errors,
       warnings
     }
   }
 }
];

const context = $('Prepare Technical Check').first().json || {};

const businessResult = $('Check Qdrant Business Collection').first().json || {};
const catalogResult = items[0]?.json || {};

function hasError(result) {
 return Boolean(
   result.error ||
   result.errorMessage ||
   result.errorDescription ||
   result.status === 'error'
 );
}

function pointsCount(result) {
 return Number(
   result.result?.points_count ??
   result.points_count ??
   result.result?.vectors_count ??
   0
 );
}

const businessError = hasError(businessResult);
const catalogError = hasError(catalogResult);

const errors = [];
const warnings = [];

if (businessError) {
 errors.push({
   code: 'qdrant_business_collection_unavailable',
   detail: businessResult
 });
}

if (catalogError) {
 errors.push({
   code: 'qdrant_catalog_collection_unavailable',
   detail: catalogResult
 });
}

const businessPoints = pointsCount(businessResult);
const catalogPoints = pointsCount(catalogResult);

if (!businessError && businessPoints === 0) {
 warnings.push({
   code: 'qdrant_business_collection_empty',
   detail: 'La colección de negocio existe pero no reporta puntos.'
 });
}

if (!catalogError && catalogPoints === 0) {
 warnings.push({
   code: 'qdrant_catalog_collection_empty',
   detail: 'La colección de catálogo existe pero no reporta puntos.'
 });
}

const status =
 errors.length > 0
   ? 'failed'
   : warnings.length > 0
     ? 'warning'
     : 'passed';

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status,
       actual_result: {
         business_collection_available: !businessError,
         catalog_collection_available: !catalogError,
         business_points_count: businessPoints,
         catalog_points_count: catalogPoints
       },
       evidence: {
         business_result: businessResult,
         catalog_result: catalogResult
       },
       errors,
       warnings
     }
   }
 }
];

const context = $('Prepare Technical Check').first().json || {};
const result = items[0]?.json || {};

const errors = [];
const warnings = [];

const hasError =
 Boolean(result.error) ||
 Boolean(result.errorMessage) ||
 Boolean(result.errorDescription);

if (hasError) {
 errors.push({
   code: 'google_drive_sample_image_unavailable',
   detail: result
 });
}

const fileName = result.name || result.fileName || '';
const mimeType = result.mimeType || result.mime_type || '';

if (!hasError && mimeType && !String(mimeType).startsWith('image/')) {
 warnings.push({
   code: 'google_drive_sample_file_not_image',
   detail: {
     fileName,
     mimeType
   }
 });
}

const status =
 errors.length > 0
   ? 'failed'
   : warnings.length > 0
     ? 'warning'
     : 'passed';

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status,
       actual_result: {
         sample_image_accessible: !hasError,
         file_name: fileName,
         mime_type: mimeType
       },
       evidence: {
         drive_result: result
       },
       errors,
       warnings
     }
   }
 }
];

const context = $('Prepare Technical Check').first().json || {};
const result = items[0]?.json || {};

const messageId =
 result.messages?.[0]?.id ||
 result.message_id ||
 result.id ||
 result.data?.messages?.[0]?.id ||
 '';

const hasError =
 Boolean(result.error) ||
 Boolean(result.errorMessage) ||
 Boolean(result.errorDescription);

const sent = Boolean(messageId) || (Object.keys(result).length > 0 && !hasError);

const errors = [];

if (!sent) {
 errors.push({
   code: 'whatsapp_test_message_failed',
   detail: result
 });
}

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status: sent ? 'passed' : 'failed',
       actual_result: {
         message_sent: sent,
         message_id: messageId
       },
       evidence: {
         whatsapp_result: result
       },
       errors,
       warnings: []
     }
   }
 }
];

const context = $('Prepare Technical Check').first().json || {};
const result = items[0]?.json || {};

const resultObject =
 result.result ||
 result.message ||
 result.data ||
 result;

const messageId =
 resultObject.message_id ||
 result.message_id ||
 result.id ||
 '';

const hasError =
 Boolean(result.error) ||
 Boolean(result.errorMessage) ||
 Boolean(result.errorDescription) ||
 result.ok === false;

const sent = Boolean(messageId) || (Object.keys(result).length > 0 && !hasError);

const errors = [];
const warnings = [];

if (!sent) {
 if (context.technical_check?.critical) {
   errors.push({
     code: 'telegram_test_message_failed',
     detail: result
   });
 } else {
   warnings.push({
     code: 'telegram_test_message_failed_non_critical',
     detail: result
   });
 }
}

const status =
 errors.length > 0
   ? 'failed'
   : warnings.length > 0
     ? 'warning'
     : 'passed';

return [
 {
   json: {
     ...context,
     technical_check_result: {
       status,
       actual_result: {
         message_sent: sent,
         message_id: String(messageId || '')
       },
       evidence: {
         telegram_result: result
       },
       errors,
       warnings
     }
   }
 }
];

function makeId(prefix) {
 return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

const input = items[0]?.json || {};
const config = input.technical_config || {};
const ctx = config.test_context || {};

const eventId = makeId('evt_error_probe');

const event = {
 schema_version: 'dalia.m8.event_request.v1',
 event: {
   event_id: eventId,
   event_name: 'error',
   event_type: 'error',
   module: 'M11',
   status: 'error',
   level: 'ERROR',
   timestamp: new Date().toISOString(),

   trace: {
     conversation_id: `conv_${ctx.channel}_${ctx.user_id}`,
     session_id: `session_${ctx.channel}_${ctx.user_id}`
   },

   context: {
     business_id: ctx.business_id || 'business_demo',
     environment: config.environment || 'demo',
     channel: ctx.channel || 'whatsapp',
     user_id: ctx.user_id || '',
     display_name: ctx.display_name || 'Tester Técnico'
   },

   correlation: {
     correlation_id: eventId,
     trace_id: eventId
   },

   payload: {
     check_type: 'error_logging_readiness',
     source: 'M11 technical rehearsal',
     recoverable: true
   },

   error: {
     error_code: 'm11_error_probe',
     error_message: 'Evento de prueba para validar logging de errores.',
     error_node: 'Build M8 Error Probe Event',
     error_workflow: 'DALIA_M11_Technical_Rehearsal_Runner'
   }
 }
};

return [
 {
   json: {
     ...input,
     m8_error_probe_event_id: eventId,
     m8_event_request: event
   }
 }
];

const base = $('Build Technical Rehearsal Run Draft').first().json || {};
const run = base.validation_run || {};

const results = items
 .map(item => item.json || {})
 .filter(row => row.check_id);

const passed = results.filter(r => r.status === 'passed').length;
const warning = results.filter(r => r.status === 'warning').length;
const failed = results.filter(r => r.status === 'failed').length;
const skipped = results.filter(r => r.status === 'skipped').length;

const criticalFailures = results.filter(r =>
 r.critical === true &&
 r.status === 'failed'
);

const goNoGo = criticalFailures.length === 0
 ? 'GO_TECHNICAL'
 : 'NO_GO_TECHNICAL';

const summary =
 goNoGo === 'GO_TECHNICAL'
   ? `Ensayo técnico aprobado. ${passed} checks passed, ${warning} warnings, ${failed} failed.`
   : `Ensayo técnico NO aprobado. Fallaron ${criticalFailures.length} checks críticos.`;

return [
 {
   json: {
     validation_run_update: {
       validation_run_id: run.validation_run_id,
       status: 'completed',
       finished_at: new Date().toISOString(),
       total_cases: results.length,
       passed_cases: passed,
       warning_cases: warning + skipped,
       failed_cases: failed,
       go_no_go: goNoGo,
       summary,
       metadata: {
         ...(run.metadata || {}),
         technical_rehearsal: {
           go_no_go: goNoGo,
           passed,
           warning,
           failed,
           skipped,
           critical_failures: criticalFailures.map(r => ({
             check_id: r.check_id,
             check_name: r.check_name,
             component: r.component
           })),
           evaluated_at: new Date().toISOString()
         }
       }
     },
     technical_rehearsal_summary: {
       go_no_go: goNoGo,
       passed,
       warning,
       failed,
       skipped,
       critical_failures: criticalFailures,
       results
     }
   }
 }
];

const input = $('Aggregate Technical Rehearsal Result').first().json || {};

return [
 {
   json: {
     schema_version: 'dalia.m11.technical_rehearsal_result.v1',
     success: input.technical_rehearsal_summary?.go_no_go === 'GO_TECHNICAL',
     result_type: 'technical_rehearsal_completed',
     summary: input.technical_rehearsal_summary,
     completed_at: new Date().toISOString()
   }
 }
];
